def test_rrf_weights_change_scores_for_same_ranked_document():
    inputs = [
        {
            "documents": [
                Document(id="shared", content="shared from input 1"),
                Document(id="only_1", content="only in input 1"),
            ]
        },
        {
            "documents": [
                Document(id="shared", content="shared from input 2"),
                Document(id="only_2", content="only in input 2"),
            ]
        },
    ]

    unweighted_join = JoinDocuments(join_mode="reciprocal_rank_fusion")
    weighted_join = JoinDocuments(join_mode="reciprocal_rank_fusion", weights=[0.8, 0.2])

    unweighted_result, _ = unweighted_join.run(deepcopy(inputs))
    weighted_result, _ = weighted_join.run(deepcopy(inputs))

    unweighted_scores = {doc.id: doc.score for doc in unweighted_result["documents"]}
    weighted_scores = {doc.id: doc.score for doc in weighted_result["documents"]}

    assert unweighted_scores["shared"] == pytest.approx(1.0)
    assert weighted_scores["shared"] == pytest.approx(1.0)
    assert weighted_scores["only_1"] > unweighted_scores["only_1"]
    assert weighted_scores["only_2"] < unweighted_scores["only_2"]

