from copy import deepcopy

import pytest

from haystack.nodes.other import JoinDocuments
from haystack.schema import Document


def test_rrf_equal_weights_matches_default_scores():
    inputs_default = [
        {
            "documents": [
                Document(id="doc-1", content="text document 1", content_type="text"),
                Document(id="doc-2", content="text document 2", content_type="text"),
            ]
        },
        {
            "documents": [
                Document(id="doc-3", content="text document 3", content_type="text"),
                Document(id="doc-4", content="text document 4", content_type="text"),
            ]
        },
    ]
    inputs_even = deepcopy(inputs_default)

    default_result, _ = JoinDocuments(join_mode="reciprocal_rank_fusion").run(inputs_default)
    even_result, _ = JoinDocuments(join_mode="reciprocal_rank_fusion", weights=[0.5, 0.5]).run(inputs_even)

    assert [doc.id for doc in default_result["documents"]] == [doc.id for doc in even_result["documents"]]
    assert [doc.score for doc in default_result["documents"]] == [doc.score for doc in even_result["documents"]]


def test_rrf_applies_uneven_weights_to_scores():
    weighted_inputs = [
        {
            "documents": [
                Document(id="shared", content="shared", content_type="text"),
                Document(id="only-first", content="only first", content_type="text"),
            ]
        },
        {
            "documents": [
                Document(id="shared", content="shared", content_type="text"),
                Document(id="only-second", content="only second", content_type="text"),
            ]
        },
    ]

    result, _ = JoinDocuments(join_mode="reciprocal_rank_fusion", weights=[0.9, 0.1]).run(weighted_inputs)
    scores = {doc.id: doc.score for doc in result["documents"]}

    assert scores["only-first"] > scores["only-second"]


def test_rrf_scores_are_normalized():
    inputs = [
        {"documents": [Document(id="shared", content="shared", content_type="text")]},
        {"documents": [Document(id="shared", content="shared", content_type="text")]},
    ]

    result, _ = JoinDocuments(join_mode="reciprocal_rank_fusion").run(inputs)

    assert len(result["documents"]) == 1
    assert result["documents"][0].score == pytest.approx(1.0)

