from sympy import Function, symbols
from sympy.printing.precedence import PRECEDENCE

x, y = symbols('x y')

def test_negative_mul_with_low_precedence_custom_function_adds_parentheses():
    class LowPrecedenceF(Function):
        precedence = PRECEDENCE["Mul"] - 5

        def _sympystr(self, printer):
            return f"{printer._print(self.args[0])} F {printer._print(self.args[1])}"

    expr = -2 * LowPrecedenceF(x, y)
    assert str(expr) == "-2*(x F y)"


def test_positive_mul_with_low_precedence_custom_function_is_parenthesized():
    class LowPrecedenceF(Function):
        precedence = PRECEDENCE["Mul"] - 5

        def _sympystr(self, printer):
            return f"{printer._print(self.args[0])} F {printer._print(self.args[1])}"

    expr = 2 * LowPrecedenceF(x, y)
    assert str(expr) == "2*(x F y)"


def test_negative_mul_with_high_precedence_custom_function_does_not_add_extra_parentheses():
